class Solution {
    public List<List<Integer>> getSkyline(int[][] buildings) {
        List<int[]> events = new java.util.ArrayList<>();
        for (int[] b : buildings) {
            events.add(new int[]{b[0], -b[2]});
            events.add(new int[]{b[1], b[2]});
        }
        events.sort((a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);
        java.util.TreeMap<Integer, Integer> heights = new java.util.TreeMap<>();
        heights.put(0, 1);
        int prevMax = 0;
        List<List<Integer>> result = new java.util.ArrayList<>();
        for (int[] e : events) {
            if (e[1] < 0) heights.merge(-e[1], 1, Integer::sum);
            else {
                int cnt = heights.get(e[1]);
                if (cnt == 1) heights.remove(e[1]);
                else heights.put(e[1], cnt - 1);
            }
            int curMax = heights.lastKey();
            if (curMax != prevMax) {
                result.add(java.util.Arrays.asList(e[0], curMax));
                prevMax = curMax;
            }
        }
        return result;
    }
}
